"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type OriginAwareAnimationPrimitiveProps = ComponentProps<typeof motion.div>;

export function OriginAwareAnimationPrimitive({ children, ...props }: OriginAwareAnimationPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {opacity: 0,scale: 0.88,transformOrigin: "top-left"}}
      animate={{opacity: 1,scale: 1}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.22, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
